function updateProductMenu(){let selected=location.pathname.endsWith('/matterhorn-mouse.html')?'matterhorn-mouse':location.pathname.endsWith('/mouse.html')?'mouse':null;if(location.pathname.endsWith('/configure.html')){try{selected=JSON.parse(new URLSearchParams(location.search).get('build')||'{}').m==='mountain'?'mountain':'character';}catch{selected='character';}}document.querySelectorAll('[data-menu-product]').forEach(a=>{if(a.dataset.menuProduct===selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}updateProductMenu();document.addEventListener('keyboard-model-change',()=>setTimeout(updateProductMenu,0));document.addEventListener('change',()=>setTimeout(updateProductMenu,0));addEventListener('popstate',updateProductMenu);